class DataPlot final:public QWidget {
public:
 WorkbenchData::DataResult result;bool residual=false;QString emptyText="No paired data";
 explicit DataPlot(QWidget*p=nullptr):QWidget(p){setMinimumHeight(qMax(220,fontMetrics().height()*9));setAccessibleName("Dataset scatter and regression plot");}
protected:
 void paintEvent(QPaintEvent*)override{QPainter p(this);p.setRenderHint(QPainter::Antialiasing);auto colors=TouchWorkbench::colors(WorkbenchViews::scopePalette(this));p.fillRect(rect(),colors.surface);p.setPen(colors.text);int tickHeight=fontMetrics().height()+6;int gutter=qMax(45,fontMetrics().horizontalAdvance("-0.000")+8);QRectF box=rect().adjusted(gutter,tickHeight,-15,-tickHeight-8);p.drawRect(box);auto y=residual?result.residuals:result.y;if(result.x.isEmpty()||y.size()!=result.x.size()){p.drawText(box,Qt::AlignCenter,emptyText);return;}
 double xmin=*std::min_element(result.x.begin(),result.x.end()),xmax=*std::max_element(result.x.begin(),result.x.end()),ymin=std::numeric_limits<double>::infinity(),ymax=-ymin;for(double yy:y)if(std::isfinite(yy)){ymin=std::min(ymin,yy);ymax=std::max(ymax,yy);}if(!residual)for(double yy:result.curveY)if(std::isfinite(yy)){ymin=std::min(ymin,yy);ymax=std::max(ymax,yy);}if(!std::isfinite(ymin))return;if(xmax==xmin){xmin-=1;xmax+=1;}if(ymax==ymin){ymin-=1;ymax+=1;}double pad=(ymax-ymin)*.08;ymin-=pad;ymax+=pad;auto map=[&](double x,double yy){return QPointF(box.left()+(x-xmin)/(xmax-xmin)*box.width(),box.bottom()-(yy-ymin)/(ymax-ymin)*box.height());};p.drawText(QRectF(0,box.top()-tickHeight/2,gutter-8,tickHeight),Qt::AlignRight,QString::number(ymax,'g',4));p.drawText(QRectF(0,box.bottom()-tickHeight/2,gutter-8,tickHeight),Qt::AlignRight,QString::number(ymin,'g',4));p.drawText(QRectF(box.left(),box.bottom()+4,90,tickHeight),Qt::AlignLeft,QString::number(xmin,'g',4));p.drawText(QRectF(box.right()-90,box.bottom()+4,90,tickHeight),Qt::AlignRight,QString::number(xmax,'g',4));p.save();p.setClipRect(box);if(ymin<0&&ymax>0){QColor c=colors.text;c.setAlpha(80);p.setPen(QPen(c,1,Qt::DashLine));p.drawLine(map(xmin,0),map(xmax,0));}if(!residual&&!result.curveX.isEmpty()){p.setPen(QPen(colors.accent,2));QPainterPath path;bool previous=false;for(int i=0;i<result.curveX.size();++i){if(!std::isfinite(result.curveY[i])){previous=false;continue;}QPointF pt=map(result.curveX[i],result.curveY[i]);if(previous)path.lineTo(pt);else path.moveTo(pt);previous=true;}p.drawPath(path);}p.setPen(colors.text);p.setBrush(QBrush(colors.text));for(int i=0;i<result.x.size();++i)if(std::isfinite(y[i]))p.drawEllipse(map(result.x[i],y[i]),3,3);p.restore();}
};
namespace {
QPushButton*button(const char*k,QWidget*p){auto*b=new WorkbenchButton(QString::fromUtf8(k),p);b->setProperty("dataTranslation",k);b->setMinimumHeight(48);b->setMinimumWidth(0);return b;}
QLabel*label(const char*k){auto*l=new QLabel(QString::fromUtf8(k));l->setProperty("dataTranslation",k);l->setWordWrap(true);l->setMinimumWidth(0);return l;}
QJsonArray jsonGrid(const WorkbenchData::Grid&g){QJsonArray a;for(const auto&r:g){QJsonArray row;for(const auto&v:r)row<<v;a<<row;}return a;}
bool readGrid(const QJsonArray&a,WorkbenchData::Grid&g){if(a.isEmpty()||a.size()>10000)return false;for(auto v:a){auto r=v.toArray();if(r.size()!=3)return false;QStringList row;for(auto x:r){if(!x.isString()||x.toString().size()>4096)return false;row<<x.toString();}g<<row;}return true;}
void items(QComboBox*b,const QList<QPair<const char*,QString>>&list){b->setMinimumWidth(0);b->setMinimumHeight(48);b->setSizeAdjustPolicy(QComboBox::AdjustToMinimumContentsLengthWithIcon);for(auto pair:list){b->addItem(QString::fromUtf8(pair.first),pair.second);b->setItemData(b->count()-1,QString::fromUtf8(pair.first),Qt::UserRole+1);}}
}
DataWorkbench::DataWorkbench(QWidget*parent):QWidget(parent){
 setObjectName("dataWorkbench");TouchWorkbench::apply(this);auto*outer=new QVBoxLayout(this);outer->setContentsMargins(8,4,8,8);outer->setSpacing(8);pages_=WorkbenchViews::tabs(this);pages_->setObjectName("dataPages");outer->addWidget(pages_,1);auto*layout=WorkbenchViews::page(pages_,"Edit");auto*results=WorkbenchViews::page(pages_,"Result");auto*library=WorkbenchViews::page(pages_,"Saved");auto*intro=label("Enter X, optional paired Y, and frequency. Blank frequency means 1. Missing values are rejected.");TouchWorkbench::role(intro,"muted");layout->addWidget(intro);
 name_=new QLineEdit;name_->setPlaceholderText("Dataset name");saved_=new QComboBox;saved_->setMinimumWidth(0);saved_->setSizeAdjustPolicy(QComboBox::AdjustToMinimumContentsLengthWithIcon);auto*save=button("Save dataset",this),*load=button("Load dataset",this);library->addWidget(WorkbenchViews::field("Dataset name",name_));library->addWidget(save);library->addWidget(saved_);library->addWidget(load);saveStatus_=new QLabel;saveStatus_->setWordWrap(true);library->addWidget(saveStatus_);
 mode_=new QComboBox;sample_=new QComboBox;model_=new QComboBox;model_->setObjectName("dataModel");count_=new QSpinBox;degree_=new QSpinBox;count_->setRange(1,10000);count_->setValue(3);degree_->setRange(1,8);degree_->setValue(2);items(mode_,{{"One variable","one"},{"Paired X / Y","paired"}});items(sample_,{{"Sample","sample"},{"Population","population"}});items(model_,{{"Descriptive statistics","summary"},{"Linear fit","linear"},{"Quadratic fit","quadratic"},{"Cubic fit","cubic"},{"Polynomial fit","polynomial"},{"Exponential fit","exponential"},{"Logarithmic fit","logarithmic"},{"Power fit","power"}});layout->addWidget(WorkbenchViews::field("Analysis",model_));auto*dimensions=new QVBoxLayout;dimensions->addWidget(WorkbenchViews::field("Data mode",mode_));dimensions->addWidget(WorkbenchViews::field("Rows",count_));layout->addLayout(dimensions);
 table_=new QTableWidget(3,3);table_->setObjectName("datasetGrid");table_->setHorizontalHeaderLabels({"X","Y","f"});WorkbenchViews::grid(table_);table_->horizontalHeader()->setMinimumSectionSize(56);table_->horizontalHeader()->setSectionResizeMode(QHeaderView::Stretch);table_->horizontalHeaderItem(2)->setToolTip("Frequency");table_->setColumnHidden(1,true);layout->addWidget(table_);layout->addWidget(WorkbenchViews::keyboard(table_));
 auto*options=button("Analysis options",this);options->setCheckable(true);layout->addWidget(options);auto*optional=new QWidget;auto*form=new QVBoxLayout(optional);form->setContentsMargins(0,0,0,0);form->addWidget(WorkbenchViews::field("Convention",sample_));degreeField_=WorkbenchViews::field("Polynomial degree",degree_);form->addWidget(degreeField_);prediction_=new QLineEdit;prediction_->setObjectName("dataPrediction");prediction_->setPlaceholderText("Optional X");predictionField_=WorkbenchViews::field("Prediction",prediction_);form->addWidget(predictionField_);layout->addWidget(optional);optional->hide();connect(options,&QPushButton::toggled,optional,&QWidget::setVisible);layout->addStretch();
 auto*actions=new QHBoxLayout;run_=button("Calculate",this);run_->setProperty("twRole","primary");run_->setObjectName("dataCompute");stop_=button("Cancel",this);auto*stop=stop_;stop->hide();auto*import=button("Import CSV",this),*exportButton=button("Export CSV",this);actions->addWidget(run_,2);actions->addWidget(stop,1);outer->addLayout(actions);library->addWidget(import);library->addWidget(exportButton);library->addStretch();
 resultCard_=new WorkbenchViews::MathCard("Result");resultCard_->setValue("","",false,"Calculate to see the result.");resultCard_->insert=[this](QString s){if(onInsert)onInsert(s);};results->addWidget(resultCard_);output_=new QTextBrowser;output_->setObjectName("dataOutput");output_->setMinimumHeight(260);results->addWidget(output_);auto*reuse=new QHBoxLayout;copy_=button("Copy result",this);insert_=button("Insert result",this);reuse->addWidget(copy_);reuse->addWidget(insert_);results->addLayout(reuse);auto*plotMode=new QComboBox;items(plotMode,{{"Scatter and fit","scatter"},{"Residual plot","residual"}});results->addWidget(plotMode);plot_=new DataPlot;results->addWidget(plot_);copy_->setEnabled(false);insert_->setEnabled(false);
 connect(run_,&QPushButton::clicked,this,[this]{compute();});connect(stop,&QPushButton::clicked,this,[this]{cancel();});connect(copy_,&QPushButton::clicked,this,[this]{QApplication::clipboard()->setText(canonical_);});connect(insert_,&QPushButton::clicked,this,[this]{if(onInsert&&!canonical_.isEmpty())onInsert(canonical_);});connect(save,&QPushButton::clicked,this,[this]{saveNamed();});connect(load,&QPushButton::clicked,this,[this]{loadNamed();});connect(import,&QPushButton::clicked,this,[this]{if(onImportCsv)onImportCsv();});connect(exportButton,&QPushButton::clicked,this,[this]{if(onExportCsv)onExportCsv(exportCsv());});connect(table_,&QTableWidget::itemChanged,this,[this]{invalidate();});connect(count_,qOverload<int>(&QSpinBox::valueChanged),this,[this](int count){table_->setRowCount(count);invalidate();});connect(mode_,qOverload<int>(&QComboBox::currentIndexChanged),this,[this]{table_->setColumnHidden(1,mode_->currentIndex()==0);invalidate();});connect(sample_,qOverload<int>(&QComboBox::currentIndexChanged),this,[this]{invalidate();});connect(model_,qOverload<int>(&QComboBox::currentIndexChanged),this,[this]{degree_->setEnabled(model_->currentData()=="polynomial");degreeField_->setVisible(model_->currentData()=="polynomial");predictionField_->setVisible(model_->currentData()!="summary");if(model_->currentData()!="summary")mode_->setCurrentIndex(1);invalidate();});connect(degree_,qOverload<int>(&QSpinBox::valueChanged),this,[this]{invalidate();});connect(prediction_,&QLineEdit::textChanged,this,[this]{invalidate();});connect(plotMode,qOverload<int>(&QComboBox::currentIndexChanged),this,[this](int index){plot_->residual=index==1;plot_->update();});degree_->setEnabled(false);degreeField_->hide();predictionField_->hide();
}
WorkbenchData::Grid DataWorkbench::grid()const{WorkbenchData::Grid g;for(int i=0;i<table_->rowCount();++i){QStringList row;for(int j=0;j<3;++j)row<<(table_->item(i,j)?table_->item(i,j)->text():QString());g<<row;}return g;}
void DataWorkbench::setGrid(const WorkbenchData::Grid&g){QSignalBlocker bt(table_),bc(count_);table_->setRowCount(g.size());count_->setValue(g.size());for(int i=0;i<g.size();++i)for(int j=0;j<3;++j)table_->setItem(i,j,new QTableWidgetItem(j<g[i].size()?g[i][j]:QString()));}
void DataWorkbench::invalidate(){if(onCancel)onCancel(generation_);++generation_;canonical_.clear();output_->clear();resultCard_->setValue("","",false,WorkbenchViews::tr(translator_,"Calculate to see the result."));plot_->result={};plot_->update();run_->setEnabled(true);run_->show();stop_->hide();copy_->setEnabled(false);insert_->setEnabled(false);if(onChanged)onChanged();}
void DataWorkbench::cancel(){invalidate();output_->setPlainText(workbenchTranslateOutput(translator_?translator_("Cancelled"):QString("Cancelled"),translator_));}
void DataWorkbench::compute(){if(auto*w=QApplication::focusWidget())w->clearFocus();QGuiApplication::inputMethod()->hide();invalidate();pages_->setCurrentIndex(1);WorkbenchData::DataRequest r;r.generation=generation_;r.rows=grid();r.paired=mode_->currentIndex()==1;r.sample=sample_->currentIndex()==0;r.model=model_->currentData().toString();r.degree=degree_->value();r.prediction=prediction_->text();output_->setPlainText(workbenchTranslateOutput(translator_?translator_("Calculating…"):QString("Calculating…"),translator_));if(onCompute){run_->setEnabled(false);run_->hide();stop_->show();onCompute(r);}else output_->setPlainText(workbenchTranslateOutput("Calculation worker unavailable.",translator_));}
void DataWorkbench::setResult(const WorkbenchData::DataResult&r){if(r.generation!=generation_)return;run_->setEnabled(true);run_->show();stop_->hide();canonical_=r.ok?r.canonical:QString();resultCard_->setValue(r.ok?r.canonical:QString(),canonical_);pages_->setCurrentIndex(1);output_->setPlainText(workbenchTranslateOutput(r.ok?r.report:r.error,translator_));copy_->setEnabled(r.ok);insert_->setEnabled(r.ok);plot_->result=r.ok?r:WorkbenchData::DataResult{};plot_->update();}
bool DataWorkbench::importCsv(const QString&text,QString*error){WorkbenchData::Grid g;if(!WorkbenchData::parseCsv(text,g,error,10001,3))return false;if(g[0][0].trimmed().compare("x",Qt::CaseInsensitive)==0)g.removeFirst();if(g.isEmpty()||g.size()>10000){if(error)*error="CSV has no data or too many rows.";return false;}bool paired=false;for(auto&r:g){if(r.size()>1&&!r[1].trimmed().isEmpty())paired=true;while(r.size()<3)r<<QString();}setGrid(g);mode_->setCurrentIndex(paired?1:0);invalidate();pages_->setCurrentIndex(0);return true;}
QString DataWorkbench::exportCsv()const{auto g=grid();g.prepend({"X","Y","Frequency"});return WorkbenchData::toCsv(g);}
void DataWorkbench::saveNamed(){QString name=name_->text().trimmed();if(name.isEmpty()||name.size()>80){saveStatus_->setText(workbenchTranslateOutput("Enter a dataset name (1–80 characters).",translator_));return;}if(named_.size()>=100&&!named_.contains(name)){saveStatus_->setText(workbenchTranslateOutput("At most 100 named datasets.",translator_));return;}named_[name]=QJsonObject{{"rows",jsonGrid(grid())},{"paired",mode_->currentIndex()==1}};QSignalBlocker b(saved_);saved_->clear();saved_->addItems(named_.keys());saved_->setCurrentText(name);saveStatus_->setText(WorkbenchViews::tr(translator_,"Saved"));if(onChanged)onChanged();}
void DataWorkbench::loadNamed(){auto o=named_[saved_->currentText()].toObject();WorkbenchData::Grid g;if(readGrid(o["rows"].toArray(),g)){setGrid(g);mode_->setCurrentIndex(o["paired"].toBool()?1:0);name_->setText(saved_->currentText());invalidate();pages_->setCurrentIndex(0);}}
QJsonObject DataWorkbench::saveState()const{return{{"schema",1},{"rows",jsonGrid(grid())},{"paired",mode_->currentIndex()==1},{"sample",sample_->currentIndex()==0},{"model",model_->currentData().toString()},{"degree",degree_->value()},{"prediction",prediction_->text()},{"name",name_->text()},{"named",named_}};}
bool DataWorkbench::restoreState(const QJsonObject&o,QString*error){auto fail=[&](){if(error)*error="Invalid dataset workspace.";return false;};WorkbenchData::Grid g;if(o["schema"].toInt()!=1||!readGrid(o["rows"].toArray(),g)||o["prediction"].toString().size()>4096)return fail();auto named=o["named"].toObject();if(named.size()>100)return fail();for(auto it=named.begin();it!=named.end();++it){WorkbenchData::Grid rows;if(it.key().isEmpty()||it.key().size()>80||!readGrid(it.value().toObject()["rows"].toArray(),rows))return fail();}setGrid(g);int m=model_->findData(o["model"].toString());model_->setCurrentIndex(m<0?0:m);mode_->setCurrentIndex(o["paired"].toBool()?1:0);sample_->setCurrentIndex(o["sample"].toBool(true)?0:1);degree_->setValue(o["degree"].toInt(2));prediction_->setText(o["prediction"].toString());name_->setText(o["name"].toString().left(80));named_=named;saved_->clear();saved_->addItems(named_.keys());invalidate();return true;}
void DataWorkbench::retranslate(std::function<QString(const char*)>fn){translator_=fn;plot_->emptyText=fn("No paired data");plot_->setAccessibleName(fn("Scatter and fit"));plot_->update();for(auto*w:findChildren<QWidget*>()){auto key=w->property("dataTranslation").toByteArray();if(!key.isEmpty()){if(auto*b=qobject_cast<QPushButton*>(w))b->setText(fn(key.constData()));else if(auto*l=qobject_cast<QLabel*>(w))l->setText(fn(key.constData()));}if(auto*c=qobject_cast<QComboBox*>(w))for(int i=0;i<c->count();++i){auto text=c->itemData(i,Qt::UserRole+1).toString();if(!text.isEmpty())c->setItemText(i,fn(text.toUtf8().constData()));}}name_->setPlaceholderText(fn("Dataset name"));prediction_->setPlaceholderText(fn("Optional X"));table_->setHorizontalHeaderLabels({"X","Y","f"});table_->horizontalHeaderItem(2)->setToolTip(fn("Frequency"));resultCard_->heading->setText(fn("Result"));if(canonical_.isEmpty())resultCard_->setValue("","",false,fn("Calculate to see the result."));WorkbenchViews::translate(this,fn);TouchWorkbench::apply(this);}
